import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int cutOffTree(int[][] forest) {
        int m = forest.length;
        int n = forest[0].length;
        List<int[]> trees = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (forest[r][c] > 1) {
                    trees.add(new int[]{forest[r][c], r, c});
                }
            }
        }
        if (trees.isEmpty()) {
            return 0;
        }
        if (forest[0][0] == 0) {
            return -1;
        }

        trees.sort(Comparator.comparingInt(a -> a[0]));
        int row = 0;
        int col = 0;
        int total = 0;
        for (int[] tree : trees) {
            int distance = shortestByBfs(forest, row, col, tree[1], tree[2]);
            if (distance < 0) {
                return -1;
            }
            total += distance;
            row = tree[1];
            col = tree[2];
        }
        return total;
    }

    private int shortestByBfs(int[][] forest, int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) {
            return 0;
        }
        int m = forest.length;
        int n = forest[0].length;
        boolean[][] seen = new boolean[m][n];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{sr, sc});
        seen[sr][sc] = true;
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();
                if (current[0] == tr && current[1] == tc) {
                    return steps;
                }
                for (int[] dir : DIRS) {
                    int nr = current[0] + dir[0];
                    int nc = current[1] + dir[1];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n || seen[nr][nc] || forest[nr][nc] == 0) {
                        continue;
                    }
                    seen[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
            steps++;
        }
        return -1;
    }
}

