    private int distanceByBfs(int[][] forest, int sr, int sc, int tr, int tc) {
        int m = forest.length;
        int n = forest[0].length;
        boolean[][] visited = new boolean[m][n];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{sr, sc, 0});
        visited[sr][sc] = true;
