            int[] current = queue.poll();
            if (current[0] == tr && current[1] == tc) {
                return current[2];
            }
            for (int[] dir : DIRS) {
                int nr = current[0] + dir[0];
                int nc = current[1] + dir[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n || visited[nr][nc] || forest[nr][nc] == 0) {
                    continue;
                }
                visited[nr][nc] = true;
                queue.offer(new int[]{nr, nc, current[2] + 1});
            }
        }
        return -1;
    }
