class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int cutOffTree(int[][] forest) {
        int m = forest.length;
        int n = forest[0].length;
        if (forest[0][0] == 0) {
            return -1;
        }
        List<int[]> trees = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (forest[r][c] > 1) {
                    trees.add(new int[]{forest[r][c], r, c});
                }
            }
        }
        trees.sort(Comparator.comparingInt(a -> a[0]));

        int total = 0;
        int row = 0;
        int col = 0;
        for (int[] tree : trees) {
            int distance = aStarDistance(forest, row, col, tree[1], tree[2]);
            if (distance < 0) {
                return -1;
            }
            total += distance;
            row = tree[1];
            col = tree[2];
        }
        return total;
    }

    private int aStarDistance(int[][] forest, int sr, int sc, int tr, int tc) {
        int m = forest.length;
        int n = forest[0].length;
        int[][] best = new int[m][n];
        for (int[] row : best) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        PriorityQueue<int[]> open = new PriorityQueue<>(Comparator.comparingInt(a -> a[3]));
        best[sr][sc] = 0;
        open.offer(new int[]{sr, sc, 0, manhattan(sr, sc, tr, tc)});
        while (!open.isEmpty()) {
            int[] current = open.poll();
            int r = current[0];
            int c = current[1];
            int walked = current[2];
            if (walked != best[r][c]) {
                continue;
            }
            if (r == tr && c == tc) {
                return walked;
            }
            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n || forest[nr][nc] == 0) {
                    continue;
                }
                int nextWalked = walked + 1;
                if (nextWalked < best[nr][nc]) {
                    best[nr][nc] = nextWalked;
                    open.offer(new int[]{nr, nc, nextWalked, nextWalked + manhattan(nr, nc, tr, tc)});
                }
            }
        }
        return -1;
    }

    private int manhattan(int r, int c, int tr, int tc) {
        return Math.abs(r - tr) + Math.abs(c - tc);
    }
}

