class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int cutOffTree(int[][] forest) {
        if (forest[0][0] == 0) {
            return -1;
        }
        List<int[]> trees = new ArrayList<>();
        for (int r = 0; r < forest.length; r++) {
            for (int c = 0; c < forest[0].length; c++) {
                if (forest[r][c] > 1) {
                    trees.add(new int[]{forest[r][c], r, c});
                }
            }
        }
        trees.sort(Comparator.comparingInt(a -> a[0]));

        int row = 0;
        int col = 0;
        int total = 0;
        for (int[] tree : trees) {
            int distance = bidirectionalBfs(forest, row, col, tree[1], tree[2]);
            if (distance < 0) {
                return -1;
            }
            total += distance;
            row = tree[1];
            col = tree[2];
        }
        return total;
    }

    private int bidirectionalBfs(int[][] forest, int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) {
            return 0;
        }
        int m = forest.length;
        int n = forest[0].length;
        Set<Integer> forward = new HashSet<>();
        Set<Integer> backward = new HashSet<>();
        boolean[][] forwardSeen = new boolean[m][n];
        boolean[][] backwardSeen = new boolean[m][n];
        forward.add(sr * n + sc);
        backward.add(tr * n + tc);
        forwardSeen[sr][sc] = true;
        backwardSeen[tr][tc] = true;
        int steps = 0;
        while (!forward.isEmpty() && !backward.isEmpty()) {
            if (forward.size() > backward.size()) {
                Set<Integer> tmp = forward;
                forward = backward;
                backward = tmp;
                boolean[][] tmpSeen = forwardSeen;
                forwardSeen = backwardSeen;
                backwardSeen = tmpSeen;
            }
            Set<Integer> next = new HashSet<>();
            steps++;
            for (int cell : forward) {
                int r = cell / n;
                int c = cell % n;
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n || forest[nr][nc] == 0 || forwardSeen[nr][nc]) {
                        continue;
                    }
                    if (backwardSeen[nr][nc]) {
                        return steps;
                    }
                    forwardSeen[nr][nc] = true;
                    next.add(nr * n + nc);
                }
            }
            forward = next;
        }
        return -1;
    }
}

