class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int cutOffTree(int[][] forest) {
        if (forest[0][0] == 0) {
            return -1;
        }
        List<int[]> trees = new ArrayList<>();
        for (int r = 0; r < forest.length; r++) {
            for (int c = 0; c < forest[0].length; c++) {
                if (forest[r][c] > 1) {
                    trees.add(new int[]{forest[r][c], r, c});
                }
            }
        }
        trees.sort(Comparator.comparingInt(a -> a[0]));

        int total = 0;
        int row = 0;
        int col = 0;
        for (int[] tree : trees) {
            int distance = uniformCostDistance(forest, row, col, tree[1], tree[2]);
            if (distance == -1) {
                return -1;
            }
            total += distance;
            row = tree[1];
            col = tree[2];
        }
        return total;
    }

    private int uniformCostDistance(int[][] forest, int sr, int sc, int tr, int tc) {
        int m = forest.length;
        int n = forest[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        PriorityQueue<int[]> frontier = new PriorityQueue<>(Comparator.comparingInt(a -> a[2]));
        dist[sr][sc] = 0;
        frontier.offer(new int[]{sr, sc, 0});
        while (!frontier.isEmpty()) {
            int[] current = frontier.poll();
            int r = current[0];
            int c = current[1];
            int cost = current[2];
            if (cost != dist[r][c]) {
                continue;
            }
            if (r == tr && c == tc) {
                return cost;
            }
            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n || forest[nr][nc] == 0) {
                    continue;
                }
                int nextCost = cost + 1;
                if (nextCost < dist[nr][nc]) {
                    dist[nr][nc] = nextCost;
                    frontier.offer(new int[]{nr, nc, nextCost});
                }
            }
        }
        return -1;
    }
}
